using System.Windows.Forms;

public class MainForm : Form
{
    private readonly StatusStrip _statusStrip;

    public MainForm()
    {
        _statusStrip = new StatusStrip();
        _statusStrip.Items.Add(new ToolStripStatusLabel("Ready"));
        Controls.Add(_statusStrip);
    }
}

using System;
using System.ComponentModel;
using System.Drawing.Design;
using System.Windows.Forms;
using System.Windows.Forms.Design;

public class MyControlEditor : UITypeEditor
{
    public override UITypeEditorEditStyle GetEditStyle(ITypeDescriptorContext? context)
        => UITypeEditorEditStyle.DropDown;

    public override object? EditValue(
        ITypeDescriptorContext? context,
        IServiceProvider? provider,
        object? value)
    {
        if (provider?.GetService(typeof(IWindowsFormsEditorService))
            is not IWindowsFormsEditorService editorService)
            return value;

        // .NET 9 breaking change: DropDownControl now throws ArgumentNullException
        // if the control argument is null. Guard against that.
        var editControl = CreateEditControl(value);
        if (editControl is null)
            return value;

        editorService.DropDownControl(editControl);
        return editControl.Tag;
    }

    private static Control? CreateEditControl(object? currentValue)
    {
        var listBox = new ListBox();
        listBox.Items.AddRange(new object[] { "Option A", "Option B", "Option C" });
        listBox.Tag = currentValue;
        listBox.Click += (s, e) =>
        {
            if (s is ListBox lb && lb.SelectedItem is not null)
                lb.Tag = lb.SelectedItem;
        };
        return listBox;
    }
}

